export type Language = 'en' | 'sv' | 'da' | 'no';

export interface LanguageOption {
  code: Language;
  name: string;
  flag: string;
}

export const LANGUAGES: LanguageOption[] = [
  { code: 'en', name: 'English', flag: '🇬🇧' },
  { code: 'sv', name: 'Svenska', flag: '🇸🇪' },
  { code: 'da', name: 'Dansk', flag: '🇩🇰' },
  { code: 'no', name: 'Norsk', flag: '🇳🇴' }
];

const SUPPORTED: Language[] = ['en', 'sv', 'da', 'no'];

/**
 * Pick a shop language from what the visitor's browser asks for.
 *
 * Browsers send tags like `sv-SE`, `nb-NO`, `da`, `en-GB`, in the visitor's order
 * of preference, so we walk that list and take the first tag we can serve rather
 * than only looking at the top one — a visitor whose first choice is German but
 * whose second is Swedish should get Swedish, not English.
 *
 * Norwegian is the awkward one: it arrives as `nb` (bokmål), `nn` (nynorsk) or
 * plain `no`, and all three map to our single `no`.
 *
 * Anything we do not sell in falls back to English.
 */
export function detectBrowserLanguage(
  candidates: readonly string[] = typeof navigator !== 'undefined'
    ? navigator.languages?.length
      ? navigator.languages
      : [navigator.language]
    : [],
): Language {
  for (const tag of candidates) {
    if (!tag) continue;
    const base = tag.toLowerCase().split('-')[0];
    if (base === 'nb' || base === 'nn' || base === 'no') return 'no';
    if ((SUPPORTED as string[]).includes(base)) return base as Language;
  }
  return 'en';
}

/** True when the value is one of the four languages the shop actually ships. */
export function isSupportedLanguage(value: unknown): value is Language {
  return typeof value === 'string' && (SUPPORTED as string[]).includes(value);
}

